INSERT INTO `visual_styles` (`style_id`, `name`, `type`, `description`, `effect_image`, `status`, `sort_order`, `created_at`, `updated_at`) VALUES
(460, '国漫动画', 'official', '整体呈现高精度国风玄幻动画质感，以修长俊美的人物比例、细腻皮肤与发丝、精致服饰硬表面装饰和电影化光色控制构成稳定的东方CG视觉基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260724_112242.png', 'online', 1, NOW(), NOW()),
(238, '影视写实', 'official', '整体呈现原创非IP的电影级写实风格，以高细节真实材质、强氛围体积光、广角环境纵深和冷暖自适应调色构成沉浸式史诗与黑色电影融合的视觉基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_141248.png', 'online', 2, NOW(), NOW()),
(1, '哥特', 'official', '一种原创非系列的电影级写实哥特恐怖视觉，强调苍白细腻质感、深暗明暗对比、冷雾氛围与可变戏剧光色。', 'https://novel-video-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/official_effect/1_20260707_180621.webp', 'online', 3, NOW(), NOW()),
(2, '迪士尼', 'official', '经典迪士尼手绘赛璐璐动画风格，强调优雅比例、清晰线条、柔和上色、胶片质感与可适配的戏剧化光影。', 'https://novel-video-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/official_effect/2_20260707_182318.jpg', 'online', 4, NOW(), NOW()),
(3, '女性漫画', 'official', '整体为日系动画风的都市时尚插画，线条干净利落、人物比例修长，质感以顺滑的柔和赛璐璐明暗为主并辅以电影感的景深虚化与霓虹高光。', 'https://novel-video-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/official_effect/3_20260707_182313.jpg', 'online', 5, NOW(), NOW()),
(4, '宫崎骏', 'official', '整体为日系手绘动画背景风格，线条干净、植被块面厚实且带颗粒质感，色彩随光线冷暖变化并营造宁静怀旧的自然氛围。', 'https://novel-video-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/official_effect/4_20260707_182314.jpg', 'online', 6, NOW(), NOW()),
(214, '2D古风', 'official', '整体呈现高精度国风仙侠插画基因，以修长人物比例、柔和工笔式线面、丝绸光泽与云雾仙境层次为核心，色彩随场景在清冷空灵、华贵鎏金与梦幻粉彩之间自适应变化。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260708_171511.png', 'online', 7, NOW(), NOW()),
(6, '皮克斯', 'official', '整体为原创非IP的高端动画电影感3D风格，强调圆润造型、夸张表情、精细毛发与皮肤材质、柔和电影级光影和适应性暖冷色彩氛围。', 'https://novel-video-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/official_effect/6_20260707_180925.webp', 'online', 8, NOW(), NOW()),
(7, '日漫', 'official', '整体为现代都市/日常向的二次元插画与条漫质感：线条干净、块面清晰、赛璐璐+柔和渐变上色，材质简洁少纹理，光影与色彩随场景在暖室内柔光与霓虹边缘光之间自适应切换。', 'https://novel-video-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/official_effect/7_20260707_180931.png', 'online', 9, NOW(), NOW()),
(8, '美漫', 'official', '整体呈现原创非IP的西方写实漫画视觉基因，以细致墨线、密集排线、低饱和土色调和纸面印刷质感构成克制而纪实的叙事氛围。', 'https://novel-video-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/official_effect/8_20260707_182435.webp', 'online', 10, NOW(), NOW()),
(9, '写实', 'official', '整体为电影级写实人像摄影风格，浅景深与微颗粒质感突出皮肤细节，光色随场景自适应并保持克制而紧张的氛围。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260703_120718.png', 'online', 11, NOW(), NOW()),
(20, '伤感像素', 'official', '整体为原创非IP的雨夜都市像素插画体系：低分辨率硬边、简化二次元面部与块面人体、冷蓝主调配少量霓虹暖光，雨线与水面反射用抖动与阶梯明度营造电影感氛围。', 'https://novel-video-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/official_effect/20_20260707_182511.jpg', 'online', 12, NOW(), NOW()),
(21, '新海诚', 'official', '整体为日系动画电影感的清线稿赛璐璐上色风格，暖光主导、柔和散景与轻微辉光，人物比例偏写实但五官简化、色彩统一且对比克制。', 'https://novel-video-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/official_effect/21_20260707_182527.webp', 'online', 13, NOW(), NOW()),
(5, '国风动漫', 'official', '整体为国风二次元插画体系：线条干净利落、五官偏锐利写实，赛璐璐分块配合柔和渐变与电影感光影，色彩以低饱和暖土色对冷绿形成张力并保持氛围可变。', 'https://novel-video-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/official_effect/5_20260707_182442.jpg', 'online', 14, NOW(), NOW()),
(215, '3D卡通', 'official', '整体呈现原创非IP的高精度Q版3D童话角色风格，强调大眼圆脸、柔滑材质、玩具般抛光质感与电影级景深光效。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260708_173825.png', 'online', 15, NOW(), NOW()),
(216, '3D古风', 'official', '非特定IP的国风仙侠电影级3D美学，强调精致写实人物、华丽材质、传统中式几何与可变的梦幻光雾氛围。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260709_102457.jpg', 'online', 16, NOW(), NOW()),
(217, '3D现代', 'official', '整体呈现原创非IP的高端都市写实3D风格，强调精致人物、现代几何空间、反射材质与可变冷暖电影光影。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260710_104910.png', 'online', 17, NOW(), NOW()),
(218, '日系复古动漫', 'official', '复古赛璐璐动画结合City Pop美学，以干净线稿、柔和渐变、胶片颗粒、霓虹反射和怀旧高饱和都市氛围为核心。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260710_110928.png', 'online', 18, NOW(), NOW()),
(219, '日系现代都市', 'official', '整体为City Pop美学主导的半写实日系动画插画风，融合精致线稿、柔和赛璐璐绘制、颗粒质感、霓虹与粉彩的自适应都市光影。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260710_111436.png', 'online', 19, NOW(), NOW()),
(220, '韩流偶像', 'official', '整体呈现韩流偶像演唱会美学的写实电影质感，以霓虹灯效、高反射材质、舞台光束和精修时尚人像构成华丽动感的视觉体系。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260710_112511.png', 'online', 20, NOW(), NOW()),
(223, 'Y2K', 'official', '整体呈现强烈Y2K千禧年流行视觉基因，以拼贴海报式版面、金属镀铬与全息材质、霓虹高饱和配色、像素界面符号和杂志感人物剪贴共同构成高密度、俏皮又复古未来感的数字流行风格。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_103939.jpg', 'online', 21, NOW(), NOW()),
(230, '中国工笔画', 'official', '整体呈现工笔重彩与古典宫廷绘画融合的国风视觉基因，线描纤细克制、设色雅淡含蓄、材质如绢本宣纸般温润，并带有文人画式的留白、雾感与端庄静雅气息。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_105127.jpg', 'online', 22, NOW(), NOW()),
(231, '乐高', 'official', '乐高玩具线风格，以积木模块结构、可见颗粒、迷你人比例和光亮塑料质感为核心，结合微缩摄影景深与可适配的电影化光色。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260710_112853.jpg', 'online', 23, NOW(), NOW()),
(232, '华丽原画', 'official', '整体呈现高精度东方二次元游戏原画气质，以华丽鎏金纹饰、晶体能量母题、流动布料轮廓和电影化发光氛围构成统一的梦幻史诗视觉基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_105602.jpg', 'online', 24, NOW(), NOW()),
(233, '吉卜力', 'official', '整体呈现经典吉卜力系二维手绘动画质感，以细铅笔线与清晰赛璐珞平涂结合纯水彩背景，在暖金自然光与怀旧大地色调中体现纸张纹理与水彩晕染。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260514_144125.jpg', 'online', 25, NOW(), NOW()),
(234, '唯美写实', 'official', '整体呈现原创非IP的电影感写实摄影风格，以高细节自然写实、柔和景深、暖金光线、季节性色彩与宁静诗意氛围为核心视觉基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_111309.jpg', 'online', 26, NOW(), NOW()),
(235, '国风漫剧', 'official', '整体呈现原创非IP的中式仙侠国风绘制体系，以飘逸人物、古典楼阁、云山水境与柔光薄雾构成唯美空灵且电影化的画面基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_114738.jpg', 'online', 27, NOW(), NOW()),
(236, '复古DV', 'official', '整体呈现90年代家用DV/VHS录像截图质感：低清软焦、扫描线与彩噪、时间戳OSD叠加，写实构图配合霓虹与路灯的氛围光，营造安静怀旧的边界空间感。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_120226.jpg', 'online', 28, NOW(), NOW()),
(237, '日系清新', 'official', '整体呈现日式生活电影感摄影风格，以柔和逆光、浅景深、低饱和怀旧色调与细腻胶片颗粒营造安静、清冷而略带感伤的季节性氛围。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_120700.png', 'online', 29, NOW(), NOW()),
(240, '怪谈漫画', 'official', '整体呈现日式黑白恐怖青年漫画质感，以高密度钢笔排线、厚重黑块与半写实造型构建压迫阴森、诡谲肃杀且可自适应光影与点状红白强调的视觉系统。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_143643.jpg', 'online', 30, NOW(), NOW()),
(241, '日漫二次元', 'official', '整体呈现高完成度日式轻小说动画视觉基因，以清透大气的场景透视、细腻角色五官、赛璐璐与厚涂融合上色、电影化光色调度与温柔梦幻氛围构成稳定风格核心。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_142818.png', 'online', 31, NOW(), NOW()),
(242, '未来主义', 'official', '整体呈现原创非IP的未来几何视觉语言，以碎片化棱角构成、强透视速度线、霓虹工业撞色、海报化明暗与颗粒质感建立高能科技黑色电影气质。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_144304.png', 'online', 32, NOW(), NOW()),
(243, '毛毡玩偶', 'official', '整体呈现原创非IP的羊毛毡微缩定格童话风，强调圆润Q版造型、可见缝线、蓬松纤维质感与柔和漫射光下的温暖治愈氛围。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_154931.jpg', 'online', 33, NOW(), NOW()),
(244, '水彩画', 'official', '整体呈现通透细腻的高品质水彩插画风格，以湿画法晕染、透明叠色、纸张肌理与柔和光色营造诗意、清新且富有旅行手账气息的自然写实视觉基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_161211.png', 'online', 34, NOW(), NOW()),
(245, '油画', 'official', '整体呈现原创非IP的欧洲古典学院派与印象派融合油画风，强调厚涂肌理、松动笔触、自然写实造型与可随场景变化的诗性光色氛围。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_165223.png', 'online', 35, NOW(), NOW()),
(246, '王家卫电影', 'official', '整体呈现港风黑色电影质感，以潮湿霓虹、低照度暖冷对比、狭窄空间透视与旧化表面纹理构成压抑而暧昧的都市夜色视觉基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_173853.png', 'online', 36, NOW(), NOW()),
(248, '皮克斯', 'official', '整体呈现原创非IP的高端动画电影绘本风格，以圆润可爱造型、细腻材质、温暖电影级光效与梦幻治愈氛围为核心视觉基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_173050.png', 'online', 37, NOW(), NOW()),
(249, '真人古风', 'official', '整体呈现原创非IP的中式古风电影级写实美学，强调汉服纹样、东方建筑雕饰、青瓷鎏金质感与薄雾光影中的雅致空灵氛围。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_181648.png', 'online', 38, NOW(), NOW()),
(251, '素描简笔画', 'official', '整体呈现日系漫画影响的黑白铅笔速写写实风，以干净线稿、轻柔排线、大面积留白和安静温暖的日常气息为核心。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_172956.png', 'online', 39, NOW(), NOW()),
(252, '古典武侠', 'official', '整体呈现原创非IP的中式武侠电影感写实风格，以山水云雾、古建筑与布料流动为核心视觉基因，色彩克制、光影低调、质感苍茫而诗意。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_172908.jpg', 'online', 40, NOW(), NOW()),
(253, '超现实奇幻', 'official', '整体呈现原创非IP的梦幻超现实童话绘景风格，以粉蓝薰衣草柔光、珍珠晶体质感、云海天穹与华丽漂浮结构构成空灵浪漫且高度细腻的视觉基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_173112.png', 'online', 41, NOW(), NOW()),
(254, '复古港片', 'official', '整体呈现老派华语武侠电视剧质感，强调复古胶片颗粒、朴素布景构图、含蓄色彩分级与薄雾环境下的写实人物与年代感。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_181727.png', 'online', 42, NOW(), NOW()),
(255, '韩漫二次元', 'official', '整体呈现韩系治愈日常插画气质，人物与场景以细腻线稿、柔和上色、清新浪漫光色和城市生活感共同构成稳定的非IP视觉基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260714_160248.png', 'online', 43, NOW(), NOW()),
(256, '鲜艳写实', 'official', '整体呈现高饱和高细节的原创纪实旅拍风格，以真实摄影质感、通透景深、电影化光色响应和鲜明冷暖对比构成浓烈而沉浸的视觉基因。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260714_160225.png', 'online', 44, NOW(), NOW()),
(258, '黏土', 'official', '整体呈现原创非IP的手工黏土定格微缩绘本风，造型圆润可爱、材质朴拙温暖、色彩柔和并带有灵活的电影化光影氛围。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_181705.png', 'online', 45, NOW(), NOW()),
(259, '黑白电影', 'official', '整体呈现原创非IP的经典黑色电影摄影基因，以银盐黑白层次、深阴影留白、体积雾与湿润反光塑造冷峻压抑且富有年代感的电影化氛围。', 'https://wawa-cnb-prod-1300456063.cos.ap-shanghai.myqcloud.com/visual_style/7457684235017523201/effect_20260713_173122.png', 'online', 46, NOW(), NOW());
